package hu.mounjarosegito.app;
import android.app.*;import android.content.*;import android.os.Build;
public class ReminderReceiver extends android.content.BroadcastReceiver{
 @Override public void onReceive(Context c,Intent i){int idx=i.getIntExtra("idx",-1);if(idx<0||idx>=ReminderScheduler.TITLES.length)return;NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);String channel="mj_reminders";if(Build.VERSION.SDK_INT>=26)nm.createNotificationChannel(new NotificationChannel(channel,"Napi emlékeztetők",NotificationManager.IMPORTANCE_DEFAULT));Intent open=new Intent(c,MainActivity.class);PendingIntent pi=PendingIntent.getActivity(c,0,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);String body=idx==5?"Csak az orvos által előírt adagot alkalmazd; ellenőrizd a receptet és a toll útmutatóját.":"Nyisd meg a Mounjaro Segítőt a mai tervhez.";Notification n=new Notification.Builder(c,channel).setSmallIcon(android.R.drawable.ic_popup_reminder).setContentTitle(ReminderScheduler.TITLES[idx]).setContentText(body).setContentIntent(pi).setAutoCancel(true).build();try{nm.notify(idx+10,n);}catch(SecurityException ignored){}ReminderScheduler.next(c);}
}
